// "cuatro con cincuenta", "12 con 50": the "con" between two numbers is the decimal point ("doce con cinco" is 12.05),
// unless a count word follows ("2 con 3 amigos").
const CON_CENTS = /(?<![\d.,])(\d+) con (\d{1,2})(?![\d.,:])(?! (?:personas?|amigos?|amigas?|niños?|hijos?|años?|d[ií]as?|meses|semanas?|horas?|minutos?|kilos?|litros?|veces)(?![\p{L}]))/gu;
const numberWords = (text: string) => baseNumberWords(text).replace(CON_CENTS, (_m, whole: string, cents: string) => `${whole}.${cents.padStart(2, '0')}`);

/** "cafés" is "café", "pizzas" is "pizza", "restaurantes" is "restaurante": the plural of a dictionary word still finds it. */
function singularForms(word: string): string[] {
  const out: string[] = [];
  if (word.length > 4 && word.endsWith('es')) out.push(word.slice(0, -2));
  if (word.length > 3 && word.endsWith('s')) out.push(word.slice(0, -1));
  return out;
}

/** "a las 9 y media", "a las 8 y cuarto", "a las 7 menos cuarto", "a las 8 y 20": the minutes said as words. */
const quarterRule: TimeRule = {
  re: /(?<![\p{L}])(?:a las|a la|sobre las|hacia las|para las) (\d{1,2}) (y media|y cuarto|menos cuarto|y (\d{1,2}))(?: (de la mañana|de la manana|por la mañana|de la tarde|por la tarde|de la noche|por la noche|del mediodía|del mediodia))?(?![\p{L}\p{N}])/iu,
  resolve: (m) => {
    let h = Number(m[1]);
    const said = m[2];
    let minute = said === 'y media' ? 30 : said === 'y cuarto' ? 15 : said === 'menos cuarto' ? 45 : Number(m[3]);
    if (said === 'menos cuarto') h -= 1;
    const part = m[4];
    if (part) {
      if (/tarde|noche|mediod/.test(part) && h < 12) h += 12;
      if (/ma[ñn]ana/.test(part) && h === 12) h = 0;
    } else if (h >= 1 && h <= 6) h += 12;
    return h >= 0 && h <= 23 && minute >= 0 && minute <= 59 ? { hour: h, minute, explicit: !!part } : null;
  },
};

/** One regex per month, full and short forms, for "cuánto gasté en agosto". */
const monthNames = (forms: string[]) => forms.map((alts) => new RegExp(`(?<![\\p{L}])(?:${alts})(?![\\p{L}])`, 'iu'));

